/** A neutral daylight scene drawn behind glass and native materials, standing in for the app's own content so the blur has something to show. */
export const backdropImage = { uri: 'data:image/jpeg;base64,' }

/**
 * The glass backdrop: a soft, grainy monochrome field with window light falling across it in slats, and a few
 * large blurred shapes. The shapes are alpha masks, so the host paints them in ink (mono) or in the tint.
 * Generated once (720 x 900 field, masks at a third of that, a 192px grain tile); they are small enough to inline.
 */
export const glassBackdrop = {
  field: {
    paper: { uri: 'data:image/jpeg;base64,' },
    void: { uri: 'data:image/jpeg;base64,' },
  },
  /** A large shape low on the left, one high on the right, a small one near the middle. */
  shapes: [{ uri: 'data:image/png;base64,' }, { uri: 'data:image/png;base64,' }, { uri: 'data:image/png;base64,' }],
  /** Mono grain, tiled over everything (white and black specks in alpha). */
  grain: { uri: 'data:image/png;base64,' },
} as const
